package com.example.alerting.event;

/**
 * How a source delivers events. Stored as text in the {@code event_sources.type} column.
 */
public enum SourceType {

    /** Events are pushed to the API by an admin or an external system. */
    PUSH,

    /** The service fetches events from an external feed on a schedule. */
    POLL,

    /** Events are generated by the built-in simulator, for demos and tests. */
    SIMULATED
}
